const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

function make(values, opts = {}) {
  const log = { opens: 0, reads: 0, closes: 0 };
  const source = {
    open: async () => {
      log.opens++;
      return {
        read: async () => {
          log.reads++;
          if (opts.readError && log.reads === opts.readErrorAt) throw opts.readError;
          return values.length ? values.shift() : null;
        },
        close: async () => { log.closes++; if (opts.closeError) throw opts.closeError; },
      };
    },
  };
  return { log, service: new EventService(source, opts.mapper) };
}

async function main() {
  // unopened generator: return() opens/closes nothing
  { const { log, service } = make(['a']); const g = service.stream(); await g.return(undefined);
    assert.deepEqual(log, { opens: 0, reads: 0, closes: 0 }); }
  // lazy open + no read-ahead + normal exhaustion
  { const { log, service } = make(['a', 'b', null]); const g = service.stream();
    assert.equal(log.opens, 0);
    assert.deepEqual(await g.next(), { value: 'A', done: false });
    assert.deepEqual([log.opens, log.reads, log.closes], [1, 1, 0]);
    assert.deepEqual(await g.next(), { value: 'B', done: false });
    assert.deepEqual([log.reads, log.closes], [2, 0]);
    assert.deepEqual(await g.next(), { value: undefined, done: true });
    assert.deepEqual([log.reads, log.closes], [3, 1]);
    await g.next(); assert.equal(log.closes, 1); }
  // consumer break
  { const { log, service } = make(['a', 'b', 'c']);
    for await (const _ of service.stream()) break;
    assert.deepEqual([log.opens, log.reads, log.closes], [1, 1, 1]); }
  // break with close failure propagates
  { const closeError = new Error('close');
    const { log, service } = make(['a', 'b'], { closeError });
    await assert.rejects(async () => { for await (const _ of service.stream()) break; }, closeError);
    assert.equal(log.closes, 1); }
  // read failure, preserved over close failure
  { const readError = new Error('read'), closeError = new Error('close');
    const { log, service } = make(['a'], { readError, readErrorAt: 2, closeError });
    const g = service.stream(); await g.next();
    await assert.rejects(g.next(), readError); assert.equal(log.closes, 1); }
  // read failure, close ok
  { const readError = new Error('read');
    const { log, service } = make([], { readError, readErrorAt: 1 });
    await assert.rejects(service.stream().next(), readError); assert.equal(log.closes, 1); }
  // mapper failure, preserved over close failure
  { const mapError = new Error('map'), closeError = new Error('close');
    const { log, service } = make(['a', 'b'], { closeError, mapper: () => { throw mapError; } });
    await assert.rejects(service.stream().next(), mapError);
    assert.deepEqual([log.reads, log.closes], [1, 1]); }
  // injected throw
  { const inj = new Error('inj'), closeError = new Error('close');
    for (const ce of [undefined, closeError]) {
      const { log, service } = make(['a', 'b'], { closeError: ce }); const g = service.stream(); await g.next();
      await assert.rejects(g.throw(inj), inj); assert.equal(log.closes, 1); assert.equal(log.reads, 1); } }
  // close failure on normal exhaustion propagates
  { const closeError = new Error('close'); const { log, service } = make(['a', null], { closeError });
    await assert.rejects(async () => { for await (const _ of service.stream()); }, closeError);
    assert.equal(log.closes, 1); }
}
module.exports = main();

